"use client"

import { TUser } from "@/src/types"
import { LogoutButton } from "../components/ui/buttons/LogoutButton.tsx/LogoutButton"
import styles from "./ProfileClient.module.scss"

export default function ProfileClient({ user }: { user: TUser }) {
    const roleLabels: Record<TUser["role"], string> = {
        patient: "Пациент",
        doctor: "Врач",
        admin: "Администратор",
    }

    return (
        <main className={styles.page}>
            <section className={styles.card}>
                <div className={styles.avatar}>
                    {user.username?.[0]?.toUpperCase() ?? "?"}
                </div>

                <h1 className={styles.title}>
                    {user.username ?? "Без имени"}
                </h1>

                <p className={styles.role}>{roleLabels[user.role]}</p>

                <div className={styles.info}>
                    <div className={styles.row}>
                        <span className={styles.label}>Почта</span>
                        <span className={styles.value}>{user.email}</span>
                    </div>
                    <div className={styles.row}>
                        <span className={styles.label}>Телефон</span>
                        <span className={styles.value}>{user.phone}</span>
                    </div>
                    <div className={styles.row}>
                        <span className={styles.label}>Роль</span>
                        <span className={styles.value}>{roleLabels[user.role]}</span>
                    </div>
                    <div className={styles.row}>
                        <span className={styles.label}>Дата регистрации</span>
                        <span className={styles.value}>
                            {new Date(user.createdAt).toLocaleDateString("ru-RU", {
                                day: "numeric",
                                month: "long",
                                year: "numeric",
                            })}
                        </span>
                    </div>
                </div>

                <div className={styles.actions}>
                    <LogoutButton />
                </div>
            </section>
        </main>
    )
}